  const call = (name, args) => codemode[name](args);
  const raw = await call({{tool}}, { parent: {{space}}, after: {{after}}, pageSize: {{page_size}}, pageToken: {{token}} });
  const v = typeof raw === "string" ? JSON.parse(raw) : raw;
