    name: m.name ?? null, createTime: m.createTime ?? null, text: String(m.text ?? "").slice(0, 2000),
    sender: { name: m.sender?.name ?? null, displayName: m.sender?.displayName ?? null },
    thread: { name: m.thread?.name ?? null } }));
  return JSON.stringify({ messages, nextPageToken: v.nextPageToken ?? null, truncated: v.truncated ?? false });
}

